lbl_inner_addone_gs:			ld (lbl_inner_addone_rs), sp
			ld sp, lbl_inner_addone
			jp ntc_xn
lbl_inner_addone_rt:			ld sp, (lbl_inner_addone_rs)
			jp ntc_xn
lbl_inner_addten_gs:			ld (lbl_inner_addten_rs), sp
			ld sp, lbl_inner_addten
			jp ntc_xn
lbl_inner_addten_rt:			ld sp, (lbl_inner_addten_rs)
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chks_c:		; call chks (normal)
			pop hl			; got
			ld de, var_chks_got
			ld b, 255
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 255
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
			inc hl
			inc de
			djnz p_chks_si1
			xor a
			ld (de), a
p_chks_si1_e:
			ld (p_chks_rs), sp
			ld sp, p_chks
			jp ntc_xn
p_chks_r:		; end of chks
			ld sp, (p_chks_rs)
			jp ntc_xn
p_area_c:		; call area (normal)
			pop hl			; a
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_area_a), de
			pop hl			; b
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_area_b), de
			ld hl, 0
			ld (var_area_area), hl
			ld (p_area_rs), sp
			ld sp, p_area
			jp ntc_xn
p_area_r:		; end of area
			ld sp, (p_area_rs)
			jp ntc_xn
p_shout_c:		; call shout (normal)
			pop hl			; txt
			ld (p_shout_a0), hl
			ld de, var_shout_txt
			ld b, 255
p_shout_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_shout_si0_e
			inc hl
			inc de
			djnz p_shout_si0
			xor a
			ld (de), a
p_shout_si0_e:
			ld (p_shout_rs), sp
			ld sp, p_shout
			jp ntc_xn
p_shout_r:		; end of shout
			ld de, (p_shout_a0)
			ld hl, var_shout_txt
			dec de
			ld a, (de)		; the destination's capacity
			ld b, a
			inc de
p_shout_so0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_shout_so0_e
			inc hl
			inc de
			djnz p_shout_so0
			xor a
			ld (de), a
p_shout_so0_e:
			ld sp, (p_shout_rs)
			jp ntc_xn
p_findpair_c:		; call findpair (normal)
			pop hl			; target
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_findpair_target), de
			ld hl, 0
			ld (var_findpair_findpair), hl
			ld hl, 0
			ld (var_findpair_x), hl
			ld hl, 0
			ld (var_findpair_y), hl
			ld (p_findpair_rs), sp
			ld sp, p_findpair
			jp ntc_xn
p_findpair_r:		; end of findpair
			ld sp, (p_findpair_rs)
			jp ntc_xn
p_inner_c:		; call inner (normal)
			ld hl, 0
			ld (var_inner_inner), hl
			ld hl, 0
			ld (var_inner_r), hl
			ld (p_inner_rs), sp
			ld sp, p_inner
			jp ntc_xn
p_inner_r:		; end of inner
			ld sp, (p_inner_rs)
			jp ntc_xn
p_helper_c:		; call helper (normal)
			ld hl, 0
			ld (var_helper_helper), hl
			ld (p_helper_rs), sp
			ld sp, p_helper
			jp ntc_xn
p_helper_r:		; end of helper
			ld sp, (p_helper_rs)
			jp ntc_xn
p_nothing_c:		; call nothing (normal)
			ld (p_nothing_rs), sp
			ld sp, p_nothing
			jp ntc_xn
p_nothing_r:		; end of nothing
			ld sp, (p_nothing_rs)
			jp ntc_xn
p_getseven_c:		; call getseven (normal)
