			ld sp, p_getseven
			jp ntc_xn
p_getseven_r:		; end of getseven
			ld sp, (p_getseven_rs)
			jp ntc_xn
p_sz_c:		; call sz (normal)
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_sz_n), de
			xor a
			ld (var_sz_sz), a
			ld (p_sz_rs), sp
			ld sp, p_sz
			jp ntc_xn
p_sz_r:		; end of sz
			ld sp, (p_sz_rs)
			jp ntc_xn
p_bumpshared_c:		; call bumpshared (normal)
			ld (p_bumpshared_rs), sp
			ld sp, p_bumpshared
			jp ntc_xn
p_bumpshared_r:		; end of bumpshared
			ld sp, (p_bumpshared_rs)
			jp ntc_xn
p_module2_helper_c:		; call helper (normal)
			ld hl, 0
			ld (var_module2_helper_helper), hl
			ld (p_module2_helper_rs), sp
			ld sp, p_module2_helper
			jp ntc_xn
p_module2_helper_r:		; end of helper
			ld sp, (p_module2_helper_rs)
			jp ntc_xn
p_mod2helper_c:		; call mod2helper (normal)
